[data-elementor-id="18"],[data-elementor-id="18"]>.e-con:has(.coolcraft),[data-elementor-id="18"] .elementor-widget-html,[data-elementor-id="18"] .elementor-widget-container{max-width:none!important;width:100%!important;margin:0!important;padding:0!important;gap:0!important}
.coolcraft{--ink:#14212b;--night:#0c1f2d;--sky:#e8f7fb;--aqua:#20b9c6;--sun:#ffb347;--cream:#fffaf1;--line:#d7e5e8;font-family:Arial,sans-serif;color:var(--ink);line-height:1.6}.coolcraft *{box-sizing:border-box}.coolcraft a{text-decoration:none}.cc-wrap{width:min(1120px,calc(100% - 40px));margin:auto}.cc-hero{background:var(--cream);padding:76px 0 72px;overflow:hidden}.cc-grid{display:grid;grid-template-columns:1.1fr .9fr;gap:50px;align-items:center}.cc-eyebrow{color:#087b88;font-size:.78rem;font-weight:800;letter-spacing:.13em;text-transform:uppercase}.coolcraft h1{font-size:clamp(2.75rem,5.8vw,5.15rem);line-height:.97;letter-spacing:-.055em;margin:14px 0 20px;color:var(--night)}.coolcraft h2{font-size:clamp(2rem,3.4vw,3.25rem);line-height:1.04;letter-spacing:-.04em;margin:0 0 14px;color:var(--night)}.cc-copy{font-size:1.1rem;max-width:590px;color:#4d6068}.cc-actions{display:flex;gap:12px;flex-wrap:wrap;margin-top:27px}.cc-btn{display:inline-block;padding:15px 22px;border-radius:999px;background:var(--night);color:white;font-weight:800}.cc-btn.alt{background:transparent;border:1px solid #9cb0b6;color:var(--night)}.cc-trust{display:flex;gap:16px;flex-wrap:wrap;margin-top:25px;font-size:.9rem;font-weight:700}.cc-trust span:before{content:'✦';color:#e79120;margin-right:7px}.cc-art{height:420px;position:relative;border-radius:32px;background:linear-gradient(135deg,#b4ecf1,#e6fbfd 65%,#fff4dc);overflow:hidden}.cc-sun{position:absolute;width:145px;height:145px;border-radius:50%;background:#ffbd56;top:36px;right:42px}.cc-unit{position:absolute;width:270px;height:190px;left:50%;top:50%;transform:translate(-50%,-39%);background:#fefefe;border:8px solid #dcebed;border-radius:25px;box-shadow:0 24px 0 #bddbe0,0 34px 40px rgba(15,64,75,.19)}.cc-unit:before{content:'';position:absolute;left:27px;right:27px;top:29px;height:56px;border-radius:12px;background:repeating-linear-gradient(0deg,#a5c7cd 0 3px,#eff9fa 3px 9px)}.cc-unit:after{content:'COOL • CALM • COVERED';position:absolute;bottom:26px;left:0;right:0;text-align:center;color:#127d8a;font-size:11px;letter-spacing:.12em;font-weight:900}.cc-wave{position:absolute;bottom:-100px;left:-10%;width:125%;height:190px;border-radius:50%;background:#0e7583;transform:rotate(-7deg)}.cc-section{padding:88px 0}.cc-pale{background:var(--sky)}.cc-intro{max-width:690px;margin-bottom:38px}.cc-label{font-size:.75rem;color:#087b88;font-weight:900;letter-spacing:.12em;text-transform:uppercase;margin-bottom:10px}.cc-tiles{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.cc-tile{background:#fff;border:1px solid var(--line);padding:28px;border-radius:18px}.cc-num{font-size:.86rem;font-weight:900;color:#e7891d}.cc-tile h3{font-size:1.22rem;margin:9px 0;color:var(--night)}.cc-tile p{margin:0;color:#587078}.cc-split{display:grid;grid-template-columns:.8fr 1.2fr;gap:65px;align-items:start}.cc-steps{border-left:2px solid #a7dde2;padding-left:28px}.cc-step{position:relative;padding:0 0 25px}.cc-step:before{content:'';position:absolute;width:12px;height:12px;left:-35px;top:7px;border-radius:50%;background:#0d9eac}.cc-step strong{display:block;color:var(--night);font-size:1.12rem}.cc-areas{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.cc-areas a{padding:13px;background:white;border:1px solid var(--line);border-radius:10px;color:var(--night);font-weight:800;text-align:center}.cc-faq{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.cc-faq details{background:white;border:1px solid var(--line);border-radius:13px;padding:18px}.cc-faq summary{cursor:pointer;font-weight:800;color:var(--night)}.cc-faq p{color:#587078}.cc-call{background:#0d7b88;color:white;border-radius:28px;padding:45px;display:flex;justify-content:space-between;align-items:center;gap:24px}.cc-call h2{color:white;margin:0}.cc-call p{margin:8px 0 0;color:#d7f4f5}.cc-call .cc-btn{background:#ffbd56;color:#382608}.cc-mobile{display:none}@media(max-width:800px){.cc-grid,.cc-split{grid-template-columns:1fr}.cc-art{height:290px}.cc-tiles,.cc-areas{grid-template-columns:repeat(2,1fr)}.cc-faq{grid-template-columns:1fr}.cc-call{display:block}.cc-call .cc-btn{margin-top:20px}}@media(max-width:520px){.cc-wrap{width:calc(100% - 28px)}.cc-hero,.cc-section{padding:60px 0}.cc-tiles,.cc-areas{grid-template-columns:1fr}.cc-mobile{display:block;position:fixed;bottom:13px;left:13px;right:13px;z-index:9999;text-align:center;padding:14px;border-radius:10px;background:#ffbd56;color:#352306;font-weight:900;box-shadow:0 12px 25px #0004}}
</style>
<div class="coolcraft"><section class="cc-hero"><div class="cc-wrap cc-grid"><div><div class="cc-eyebrow">South African climate care</div><h1>Make every room feel right.</h1><p class="cc-copy">Repair, service and installation support for air conditioning systems that have stopped doing their job. Clear advice, practical solutions, and help for homes and workplaces.</p><div class="cc-actions"><a class="cc-btn" href="tel:0816150876">Speak to a technician</a><a class="cc-btn alt" href="/enquire/">Tell us what’s happening</a></div><div class="cc-trust"><span>Major brands supported</span><span>Homes & businesses</span><span>Helpful local guidance</span></div></div><div class="cc-art" aria-label="Illustration of an air conditioner"><div class="cc-sun"></div><div class="cc-unit"></div><div class="cc-wave"></div></div></div></section><section class="cc-section"><div class="cc-wrap"><div class="cc-intro"><div class="cc-label">What we can help with</div><h2>From an unexpected fault to a better long-term setup.</h2><p class="cc-copy">Choose the service that fits the issue. We’ll help you understand the likely cause and what a sensible next step looks like.</p></div><div class="cc-tiles"><article class="cc-tile"><div class="cc-num">01 / Restore</div><h3>Repair & fault finding</h3><p>For units that are warm, noisy, leaking, tripping power, or refusing to start.</p></article><article class="cc-tile"><div class="cc-num">02 / Refresh</div><h3>Servicing & cleaning</h3><p>Keep airflow clear, components checked and everyday performance on track.</p></article><article class="cc-tile"><div class="cc-num">03 / Rework</div><h3>Installation & replacement</h3><p>New systems and sensible upgrades for comfortable rooms and busy spaces.</p></article></div></div></section><section class="cc-section cc-pale"><div class="cc-wrap cc-split"><div><div class="cc-label">A simpler call-out</div><h2>Tell us the symptom. We’ll help narrow it down.</h2><p class="cc-copy">No vague promises. Start with what your system is doing, then get advice suited to your property and equipment.</p><a class="cc-btn" href="tel:0816150876">Call 081 615 0876</a></div><div class="cc-steps"><div class="cc-step"><strong>It’s not cooling</strong><span>Warm air, slow cooling or short cycling can point to several causes.</span></div><div class="cc-step"><strong>It’s leaking or smelling unusual</strong><span>Water, odours or a blocked drain should be assessed before the problem grows.</span></div><div class="cc-step"><strong>It’s loud, weak or won’t turn on</strong><span>Unusual sound, poor airflow and electrical faults all need a proper check.</span></div></div></div></section><section class="cc-section"><div class="cc-wrap"><div class="cc-intro"><div class="cc-label">Find nearby information</div><h2>Start with your area.</h2><p class="cc-copy">Browse local pages for aircon repair details in major service areas.</p></div><div class="cc-areas"><a href="/air-con-repairs-in-johannesburg/">Johannesburg</a><a href="/air-con-repairs-in-pretoria/">Pretoria</a><a href="/air-con-repairs-in-cape-town/">Cape Town</a><a href="/air-con-repairs-in-durban/">Durban</a><a href="/air-con-repairs-in-bloemfontein/">Bloemfontein</a><a href="/air-con-repairs-in-gqeberha/">Gqeberha</a><a href="/air-con-repairs-in-polokwane/">Polokwane</a><a href="/air-con-repairs-across-south-africa/">All service areas</a></div></div></section><section class="cc-section cc-pale"><div class="cc-wrap"><div class="cc-intro"><div class="cc-label">Useful answers</div><h2>Before you book.</h2></div><div class="cc-faq"><details><summary>Why would an aircon stop cooling properly?</summary><p>Dirty filters, restricted airflow, component faults and refrigerant-related issues can all contribute. The exact cause needs an assessment.</p></details><details><summary>How often should it be serviced?</summary><p>The best schedule depends on use and environment. Regular attention is especially valuable for frequently used home and business systems.</p></details><details><summary>Can an older unit still be worth repairing?</summary><p>That depends on its condition, efficiency and repair history. We can help weigh repair against replacement.</p></details><details><summary>Do you work with commercial systems too?</summary><p>Yes. We support air conditioning needs for homes, offices, shops and other working spaces.</p></details></div></div></section><section class="cc-section"><div class="cc-wrap"><div class="cc-call"><div><h2>Comfort starts with the right next step.</h2><p>Call to discuss a repair, service visit or new installation.</p></div><a class="cc-btn" href="tel:0816150876">Call 081 615 0876</a></div></div></section><a class="cc-mobile" href="tel:0816150876">Call 081 615 0876</a></div>"},"elements":[],"widgetType":"html"}],"isInner":false}]

