ursor:pointer}.ar-links{display:flex;gap:10px;flex-wrap:wrap}.ar-links a{background:#fff;border:1px solid #cde3eb;color:var(--navy);font-weight:800;padding:9px 14px;border-radius:99px}.ar-cta{background:var(--navy);color:#fff;border-radius:22px;padding:42px;display:flex;justify-content:space-between;gap:25px;align-items:center}.ar-cta h2{color:#fff;margin-bottom:5px}.ar-mobile{display:none;position:fixed;z-index:9999;bottom:13px;left:14px;right:14px;background:var(--lime);color:#183700;text-align:center;font-weight:900;padding:14px;border-radius:10px}
